head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[textarea > E > oneditkeyup]<br/>Textarea 컴포넌트의 입력창에서 눌렀던 키보드의 키를 떼면 발생합니다.",
    "validation" : [
        "Textarea 컴포넌트의 입력창에서 키보드의 키를 떼면 oneditkeyup 이벤트가 발생합니다.",
        "info 객체로 입력 정보(keyCode, oldValue, newValue) 가 핸들러에 전달됩니다.",
        "이벤트 객체 e (KeyboardEvent) 가 핸들러에 전달됩니다.",
        "키 입력 시 'onkeyup -> [oneditfull] -> oneditkeyup' 순서로 이벤트가 발생합니다.",
    ]
}



scwin.onpageload = function () {
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정 (target - textarea)
    let maxByteLengthVal = con_maxByteLength.getValue();
    let properties = {};
    if (maxByteLengthVal !== "") {
        properties.maxByteLength = maxByteLengthVal;
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onkeyup", "oneditfull", "oneditkeyup"]);

    // target1 (textarea) 생성
    $c.gcm.createBasicTextArea(cList, eList);
}



// par_setValue 콤보로 선택된 값을 textarea 에 setValue → keyup 디스패치로 oneditkeyup(+조건부 oneditfull) 발화 검증
scwin.btn_setValue_onclick = function (e) {
    let val = par_setValue.getValue();
    target1.setValue(val);
    target1.focus();
    if (val !== "") {
        let lastCh = val.charAt(val.length - 1);
        let keyCode = lastCh.charCodeAt(0);
        target1.render.dispatchEvent(new KeyboardEvent('keyup', { bubbles: true, keyCode: keyCode }));
    }
};


// 현재 입력값 확인
scwin.btn_getText_onclick = function (e) {
    let rtn = target1.getValue();
    wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);
};


// onkeyup 이벤트 핸들러 (이벤트 순서 확인용)
scwin.target1_onkeyup = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onkeyup 이벤트 발생=====");
}


// oneditfull 이벤트 핸들러 (이벤트 순서 확인용)
scwin.target1_oneditfull = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_oneditfull 이벤트 발생=====");
}


// oneditkeyup 이벤트 핸들러 - info 객체 속성과 e 객체 전달 확인
scwin.target1_oneditkeyup = function (info, e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_oneditkeyup 이벤트 발생=====");
    wf_body_bottom.getObj("scwin").setReturnValue("info.keyCode : " + info.keyCode);
    wf_body_bottom.getObj("scwin").setReturnValue("info.oldValue : " + info.oldValue);
    wf_body_bottom.getObj("scwin").setReturnValue("info.newValue : " + info.newValue);
    wf_body_bottom.getObj("scwin").setReturnValue("e : " + e);
}
